test('the inherited 1500000ms build timeout cannot extend the hard 45000ms readiness deadline',async()=>{
 const f=readinessFixture({timeoutMs:1500000,steps:[{focus:readinessImmersiveFocus}],commandCost:100});
 await assert.rejects(prepareAndroidNative(f.options),/within 45000ms/);
 assert(f.elapsed<=45000);assert(f.commands.every(x=>x.timeout>0&&x.timeout<=20000&&x.timeout<=45000-x.at));
 assert.equal(f.phases.some(x=>x.stage==='ready'),false);
});
test('every setup and query ADB timeout is clamped to the same remaining readiness budget',async()=>{
 const f=readinessFixture({timeoutMs:1000,commandCost:300});await assert.rejects(prepareAndroidNative(f.options),/within 1000ms/);
 assert(f.commands.every(x=>x.timeout>0&&x.timeout<=1000-x.at));assert(f.commands.every(x=>x.at<1000));
 assert.equal(f.phases.some(x=>x.stage==='ready'),false);
});
